-- Run after 001_schema.sql, 002_rls_policies.sql and 003_seed.sql.
-- Adds the expanded launch editorial library and updates existing demo articles.
on conflict (slug) do update set title=excluded.title,category=excluded.category,excerpt=excluded.excerpt,body=excluded.body,hero_image_url=excluded.hero_image_url,status=excluded.status,is_expert_content=excluded.is_expert_content,published_at=excluded.published_at;
